package cn.zhuatech.audit;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.*;import java.util.regex.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.httpBasic;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class DeepAuditOpsTests{@Autowired MockMvc mvc;String hash="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
 @Test void engagementWorkpaperFindingAndClosureFormClosedLoop()throws Exception{long e=create("IA-DEEP-1");postAdmin("/api/admin/audit-ops/engagements/"+e+"/approve","{}").andExpect(status().isOk());post("/api/audit-ops/engagements/"+e+"/start","{}").andExpect(jsonPath("$.data.status").value("IN_PROGRESS"));long w=id(post("/api/audit-ops/engagements/"+e+"/workpapers","{\"paperNo\":\"WP-1\",\"procedure\":\"抽样核对付款审批\",\"evidenceHash\":\""+hash+"\",\"preparer\":\"auditor-a\"}").andReturn());post("/api/audit-ops/workpapers/"+w+"/submit","{}");postAdmin("/api/admin/audit-ops/workpapers/"+w+"/review","{\"reviewer\":\"reviewer-b\",\"note\":\"证据充分\",\"approved\":true}").andExpect(jsonPath("$.data.status").value("REVIEWED"));long f=id(post("/api/audit-ops/engagements/"+e+"/findings","{\"findingNo\":\"F-1\",\"severity\":\"HIGH\",\"condition\":\"付款抽样缺少复核\",\"rootCause\":\"职责配置不清\",\"recommendation\":\"增加二级复核\",\"owner\":\"财务负责人\",\"dueDate\":\"2026-10-01\"}").andReturn());post("/api/audit-ops/findings/"+f+"/action-plan","{\"actionPlan\":\"上线二级审批\"}");post("/api/audit-ops/findings/"+f+"/remediate","{\"evidenceHash\":\""+hash+"\"}");postAdmin("/api/admin/audit-ops/findings/"+f+"/verify","{\"effective\":true,\"note\":\"抽查有效\"}").andExpect(jsonPath("$.data.status").value("CLOSED"));postAdmin("/api/admin/audit-ops/engagements/"+e+"/issue-report","{}").andExpect(jsonPath("$.data.status").value("REPORT_ISSUED"));postAdmin("/api/admin/audit-ops/engagements/"+e+"/close","{}").andExpect(jsonPath("$.data.status").value("CLOSED"));}
 @Test void reportGateAndSegregationOfDutiesAreEnforced()throws Exception{long e=create("IA-DEEP-2");postAdmin("/api/admin/audit-ops/engagements/"+e+"/approve","{}");post("/api/audit-ops/engagements/"+e+"/start","{}");postAdmin("/api/admin/audit-ops/engagements/"+e+"/issue-report","{}").andExpect(status().isConflict());long w=id(post("/api/audit-ops/engagements/"+e+"/workpapers","{\"paperNo\":\"WP-2\",\"procedure\":\"检查权限\",\"evidenceHash\":\""+hash+"\",\"preparer\":\"same-user\"}").andReturn());post("/api/audit-ops/workpapers/"+w+"/submit","{}");postAdmin("/api/admin/audit-ops/workpapers/"+w+"/review","{\"reviewer\":\"same-user\",\"note\":\"自审\",\"approved\":true}").andExpect(status().isConflict());}
 @Test void duplicateProjectAndInvalidDateAreRejected()throws Exception{create("IA-DEEP-3");post("/api/audit-ops/engagements",body("IA-DEEP-3")).andExpect(status().isConflict());post("/api/audit-ops/engagements",body("IA-BAD").replace("2026-09-01","2026-12-01").replace("2026-10-01","2026-01-01")).andExpect(status().isBadRequest());mvc.perform(get("/api/audit-ops/dashboard").param("organizationCode","ZH-SH").with(httpBasic("operator","operator123"))).andExpect(status().isOk()).andExpect(jsonPath("$.data.engagements").isArray());}
 long create(String no)throws Exception{return id(post("/api/audit-ops/engagements",body(no)).andReturn());}String body(String no){return "{\"organizationCode\":\"ZH-SH\",\"projectNo\":\""+no+"\",\"title\":\"采购付款专项审计\",\"scope\":\"采购到付款全流程\",\"riskLevel\":\"HIGH\",\"leadAuditor\":\"审计经理\",\"plannedStart\":\"2026-09-01\",\"plannedEnd\":\"2026-10-01\"}";}ResultActions post(String u,String b)throws Exception{return mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post(u).with(httpBasic("operator","operator123")).contentType(MediaType.APPLICATION_JSON).content(b));}ResultActions postAdmin(String u,String b)throws Exception{return mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post(u).with(httpBasic("admin","admin123")).contentType(MediaType.APPLICATION_JSON).content(b));}long id(MvcResult r)throws Exception{var m=Pattern.compile("\"id\":(\\d+)").matcher(r.getResponse().getContentAsString());Assertions.assertTrue(m.find());return Long.parseLong(m.group(1));}}
